svg.script:
(function () {
  const baseBig = [-6, -3, 9, -2, 7, -4, -1, 8, -5, 0, 5, -8, 1, 4, -7, 2, -9, 3, 6];
  const defaultPot = [6, 9, 8, 10, 8, 9, 6];
  const cycles = [[{"big_index": 5, "sign": 1}, {"big_index": 1, "sign": -1}, {"big_index": 0, "sign": 1}, {"big_index": 3, "sign": -1}, {"big_index": 8, "sign": 1}, {"big_index": 9, "sign": -1}], [{"big_index": 6, "sign": 1}, {"big_index": 2, "sign": -1}, {"big_index": 1, "sign": 1}, {"big_index": 4, "sign": -1}, {"big_index": 9, "sign": 1}, {"big_index": 10, "sign": -1}], [{"big_index": 9, "sign": 1}, {"big_index": 4, "sign": -1}, {"big_index": 3, "sign": 1}, {"big_index": 7, "sign": -1}, {"big_index": 12, "sign": 1}, {"big_index": 13, "sign": -1}], [{"big_index": 10, "sign": 1}, {"big_index": 5, "sign": -1}, {"big_index": 4, "sign": 1}, {"big_index": 8, "sign": -1}, {"big_index": 13, "sign": 1}, {"big_index": 14, "sign": -1}], [{"big_index": 11, "sign": 1}, {"big_index": 6, "sign": -1}, {"big_index": 5, "sign": 1}, {"big_index": 9, "sign": -1}, {"big_index": 14, "sign": 1}, {"big_index": 15, "sign": -1}], [{"big_index": 14, "sign": 1}, {"big_index": 9, "sign": -1}, {"big_index": 8, "sign": 1}, {"big_index": 12, "sign": -1}, {"big_index": 16, "sign": 1}, {"big_index": 17, "sign": -1}], [{"big_index": 15, "sign": 1}, {"big_index": 10, "sign": -1}, {"big_index": 9, "sign": 1}, {"big_index": 13, "sign": -1}, {"big_index": 17, "sign": 1}, {"big_index": 18, "sign": -1}]];
  const potValues = defaultPot.slice();
  let selectedPot = null;
  let previewMode = 'plus'; // 'plus' or 'minus'

  const potFillEls = potValues.map((_, i) => document.getElementById('pot-fill-' + i));
  const potOutlineEls = potValues.map((_, i) => document.getElementById('pot-outline-' + i));
  const potNumEls = potValues.map((_, i) => document.getElementById('pot-num-' + i));
  const potHitEls = potValues.map((_, i) => document.getElementById('pot-hit-' + i));
  const bigNumEls = baseBig.map((_, i) => document.getElementById('big-num-' + i));
  const bigOutlineEls = baseBig.map((_, i) => document.getElementById('big-outline-' + i));
  const pmEls = baseBig.map((_, i) => document.getElementById('pm-' + i));
  const plusBtn = document.getElementById('btn-plus');
  const minusBtn = document.getElementById('btn-minus');
  const resetBtn = document.getElementById('btn-reset');
  const plusFace = plusBtn.querySelector('.button-face');
  const minusFace = minusBtn.querySelector('.button-face');
  const selectionLabel = document.getElementById('selection-label');
  const previewLabel = document.getElementById('preview-label');
  const dupLine = document.getElementById('dup-line');
  const rangeLine = document.getElementById('range-line');

  function computeBigValues() {
    const values = baseBig.slice();
    for (let p = 0; p < potValues.length; p++) {
      const delta = potValues[p] - defaultPot[p];
      if (delta === 0) continue;
      for (const item of cycles[p]) {
        values[item.big_index] += delta * (-item.sign);
      }
    }
    return values;
  }

  function sortedUnique(arr) {
    return Array.from(new Set(arr)).sort((a, b) => a - b);
  }

  function updateValidation(values) {
    const counts = new Map();
    for (const v of values) counts.set(v, (counts.get(v) || 0) + 1);
    const duplicates = sortedUnique(values.filter(v => (counts.get(v) || 0) > 1));
    const outOfRange = values.filter(v => v < -9 || v > 9);
    const outUnique = sortedUnique(outOfRange);

    for (let i = 0; i < values.length; i++) {
      const v = values[i];
      bigNumEls[i].textContent = String(v);
      const bad = (counts.get(v) || 0) > 1 || v < -9 || v > 9;
      bigNumEls[i].classList.toggle('bad', bad);
    }

    if (duplicates.length === 0) {
      dupLine.textContent = 'Duplicates: none';
      dupLine.setAttribute('class', 'status-line good');
    } else {
      dupLine.textContent = 'Duplicates: ' + duplicates.join(', ');
      dupLine.setAttribute('class', 'status-line bad');
    }

    if (outUnique.length === 0) {
      rangeLine.textContent = 'Out of range: none';
      rangeLine.setAttribute('class', 'status-line good');
    } else {
      rangeLine.textContent = 'Out of range: ' + outUnique.join(', ');
      rangeLine.setAttribute('class', 'status-line bad');
    }
  }

  function clearBigPreview() {
    for (let i = 0; i < bigOutlineEls.length; i++) {
      bigOutlineEls[i].classList.remove('big-outline-affected-plus', 'big-outline-affected-minus', 'big-outline-gentle');
      pmEls[i].classList.remove('pm-visible', 'pm-plus', 'pm-minus');
      pmEls[i].textContent = '';
    }
  }

  function updateSelectionStyles() {
    for (let i = 0; i < potValues.length; i++) {
      const selected = i === selectedPot;
      potFillEls[i].setAttribute('visibility', selected ? 'visible' : 'hidden');
      potOutlineEls[i].classList.toggle('pot-outline-selected', selected);
    }
  }

  function updatePreview() {
    clearBigPreview();
    plusFace.classList.remove('active-plus');
    minusFace.classList.remove('active-minus');
    if (previewMode === 'plus') plusFace.classList.add('active-plus');
    else minusFace.classList.add('active-minus');

    if (selectedPot === null) {
      selectionLabel.textContent = '';
      previewLabel.textContent = '';
      return;
    }

    selectionLabel.textContent = '';
    previewLabel.textContent = '';

    for (const item of cycles[selectedPot]) {
      const idx = item.big_index;
      const eff = previewMode === 'plus' ? -item.sign : item.sign;
      const plus = eff > 0;
      bigOutlineEls[idx].classList.add('big-outline-gentle');
      bigOutlineEls[idx].classList.add(plus ? 'big-outline-affected-plus' : 'big-outline-affected-minus');
      pmEls[idx].classList.add('pm-visible', plus ? 'pm-plus' : 'pm-minus');
      pmEls[idx].textContent = plus ? '+1' : '−1';
    }
  }

  function render() {
    for (let i = 0; i < potValues.length; i++) {
      potNumEls[i].textContent = String(potValues[i]);
    }
    updateSelectionStyles();
    updatePreview();
    updateValidation(computeBigValues());
  }

  function applyDelta(delta) {
    if (selectedPot === null) return;
    potValues[selectedPot] += delta;
    render();
  }

  function resetAll() {
    for (let i = 0; i < potValues.length; i++) {
      potValues[i] = defaultPot[i];
    }
    selectedPot = null;
    previewMode = 'plus';
    render();
  }

  function selectPot(i) {
    selectedPot = i;
    render();
  }

  function setPreview(mode) {
    previewMode = mode;
    updatePreview();
  }

  // Potential cell interactions
  potHitEls.forEach((el, i) => {
    el.addEventListener('click', (ev) => {
      ev.preventDefault();
      selectPot(i);
    });
    el.addEventListener('keydown', (ev) => {
      if (ev.key === 'Enter' || ev.key === ' ') {
        ev.preventDefault();
        selectPot(i);
      } else if (ev.key === '+' || ev.key === '=') {
        ev.preventDefault();
        selectPot(i);
        applyDelta(1);
      } else if (ev.key === '-' || ev.key === '_') {
        ev.preventDefault();
        selectPot(i);
        applyDelta(-1);
      }
    });
  });

  // Button interactions
  plusBtn.addEventListener('mouseenter', () => setPreview('plus'));
  plusBtn.addEventListener('focus', () => setPreview('plus'));
  plusBtn.addEventListener('click', (ev) => { ev.preventDefault(); setPreview('plus'); applyDelta(1); });
  plusBtn.addEventListener('keydown', (ev) => {
    if (ev.key === 'Enter' || ev.key === ' ') { ev.preventDefault(); setPreview('plus'); applyDelta(1); }
  });

  minusBtn.addEventListener('mouseenter', () => setPreview('minus'));
  minusBtn.addEventListener('focus', () => setPreview('minus'));
  minusBtn.addEventListener('click', (ev) => { ev.preventDefault(); setPreview('minus'); applyDelta(-1); });
  minusBtn.addEventListener('keydown', (ev) => {
    if (ev.key === 'Enter' || ev.key === ' ') { ev.preventDefault(); setPreview('minus'); applyDelta(-1); }
  });

  resetBtn.addEventListener('click', (ev) => { ev.preventDefault(); resetAll(); });
  resetBtn.addEventListener('keydown', (ev) => {
    if (ev.key === 'Enter' || ev.key === ' ') { ev.preventDefault(); resetAll(); }
  });

  // Global keyboard shortcuts when something inside the SVG is focused
  document.addEventListener('keydown', (ev) => {
    const active = document.activeElement;
    const inside = active && active.ownerSVGElement && active.ownerSVGElement.id === 'potential-field-demo';
    if (!inside) return;
    if (ev.key === '+' || ev.key === '=') {
      ev.preventDefault();
      setPreview('plus');
      applyDelta(1);
    } else if (ev.key === '-' || ev.key === '_') {
      ev.preventDefault();
      setPreview('minus');
      applyDelta(-1);
    } else if (ev.key === 'r' || ev.key === 'R') {
      ev.preventDefault();
      resetAll();
    }
  });

  render();
})();
